  "titre": "noImplicitReturns",
  "niveau": "elementaire",
  "ts": "type Level = \"beginner\" | \"expert\";\n\n// Version d'origine (cas \"expert\" oublié) — refusée :\n// @ts-expect-error — TS7030 : tous les chemins ne renvoient pas de valeur\nfunction brokenLevelLabel(level: Level) {\n  if (level === \"beginner\") {\n    return \"Débutant\";\n  }\n}\n\n// Version annotée mais toujours incomplète — refusée :\n// @ts-expect-error — TS2366 : il manque un return final\nfunction brokenAnnotatedLevelLabel(level: Level): string {\n  if (level === \"beginner\") {\n    return \"Débutant\";\n  }\n}\n\n// 2. Version corrigée\nfunction levelLabel(level: Level): string {\n  if (level === \"beginner\") {\n    return \"Débutant\";\n  }\n  return \"Expert\";\n}\n\nconsole.log(`${levelLabel(\"beginner\")} / ${levelLabel(\"expert\")}`);\n// À l'exécution, la version cassée renvoie undefined pour \"expert\" :\nconsole.log(brokenLevelLabel(\"expert\"));\nvoid brokenAnnotatedLevelLabel;\n\nexport {};",
  "js": "// Exercice 3 · ★★☆☆ Élémentaire — noImplicitReturns\n//\n// 1. Sans annotation, le compilateur signale :\n//    TS7030 — Not all code paths return a value.\n// 3. Avec l'annotation `: string` (avant correction), le message devient :\n//    TS2366 — Function lacks ending return statement and return type does not\n//    include 'undefined'.\n// Version d'origine (cas \"expert\" oublié) — refusée :\n// @ts-expect-error — TS7030 : tous les chemins ne renvoient pas de valeur\nfunction brokenLevelLabel(level) {\n    if (level === \"beginner\") {\n        return \"Débutant\";\n    }\n}\n// Version annotée mais toujours incomplète — refusée :\n// @ts-expect-error — TS2366 : il manque un return final\nfunction brokenAnnotatedLevelLabel(level) {\n    if (level === \"beginner\") {\n        return \"Débutant\";\n    }\n}\n// 2. Version corrigée\nfunction levelLabel(level) {\n    if (level === \"beginner\") {\n        return \"Débutant\";\n    }\n    return \"Expert\";\n}\nconsole.log(`${levelLabel(\"beginner\")} / ${levelLabel(\"expert\")}`);\n// À l'exécution, la version cassée renvoie undefined pour \"expert\" :\nconsole.log(brokenLevelLabel(\"expert\"));\nvoid brokenAnnotatedLevelLabel;\nexport {};",
