  "js": "// Exercice 12 · ★★☆☆ Élémentaire — readonly et propriétés optionnelles\n//\n// 3) Le type de task.description est string | undefined.\n//    Différence :\n//    - description?: string             → la clé peut être absente de l'objet.\n//    - description: string | undefined  → la clé doit être présente, mais peut\n//      valoir undefined (il faut écrire description: undefined explicitement).\nconst task = { id: \"t1\", name: \"Flyer\", createdAt: new Date() };\n// 1) readonly : la réaffectation est refusée\n// @ts-expect-error — Cannot assign to 'createdAt' because it is a read-only property\ntask.createdAt = new Date();\nfunction describeTask(task) {\n    return `${task.name} : ${task.description ?? \"(aucune description)\"}`;\n}\nconsole.log(describeTask(task));\nconsole.log(describeTask({ ...task, description: \"Flyer A5 recto-verso\" }));\n// @ts-expect-error — Property 'description' is missing\nconst missing = { name: \"Flyer\" };\nvoid missing;\nexport {};",
